css:
.resume{max-width: 800px;
      width: 100%;
      background: #ffffff;
      box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
      border-radius: 4px;
      padding: 2.2rem 2.5rem;
      color: #1e2b3c;
      line-height: 1.5;
      font-size: 10.5pt;
      transition: all 0.2s;}
.resume{font-family: 'Calibri', 'Arial', 'Helvetica Neue', 'Noto Sans SC', '思源黑体', sans-serif;}
.resume h1, .resume h2, .resume h3, .resume p, .resume li, .resume div, .resume span{color: #1e2b3c;}
.header{margin-bottom: 1.8rem;}
.name{font-size: 28pt;
      font-weight: 700;
      letter-spacing: 1px;
      color: #0b2b44;
      line-height: 1.2;
      margin-bottom: 0.2rem;
      font-family: 'Calibri', 'Helvetica Neue', 'Noto Sans SC', '思源黑体', sans-serif;}
.title-tag{font-size: 12pt;
      font-weight: 400;
      color: #2c3e50;
      margin-bottom: 0.8rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;}
.title-tag::after{content: "";
      flex: 1;
      height: 1px;
      background: #cbd5e0;
      margin-left: 0.75rem;}
.contact-row{display: flex;
      flex-wrap: wrap;
      gap: 1.2rem;
      font-size: 9.5pt;
      color: #2d3a4a;
      margin-top: 0.3rem;
      font-family: 'Calibri', 'Arial', 'Helvetica Neue', 'Noto Sans SC', sans-serif;}
.contact-item{display: flex;
      align-items: center;
      gap: 0.3rem;}
.contact-icon{font-size: 10pt;
      color: #2c5282;
      font-weight: 500;}
.divider{border: none;
      border-top: 1.5px solid #dce3ea;
      margin: 1.2rem 0 1.5rem 0;}
.section-title{font-size: 10.5pt;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.2px;
      color: #0b2b44;
      margin-bottom: 0.8rem;
      display: flex;
      align-items: center;
      gap: 0.5rem;
      font-family: 'Calibri', 'Helvetica Neue', 'Noto Sans SC', '思源黑体', sans-serif;}
.section-title::after{content: "";
      flex: 1;
      height: 1px;
      background: #cbd5e0;
      margin-left: 0.5rem;}
.item{margin-bottom: 1.1rem;}
.item-header{display: flex;
      justify-content: space-between;
      align-items: baseline;
      flex-wrap: wrap;
      margin-bottom: 0.15rem;}
.item-left{font-weight: 700;
      font-size: 11pt;
      color: #0b2b44;}
.item-left .company{font-weight: 700;}
.item-left .role{font-weight: 500;
      color: #2c3e50;
      margin-left: 0.3rem;
      font-size: 10.5pt;}
.item-right{font-weight: 400;
      font-size: 9.5pt;
      color: #4a5c6c;
      white-space: nowrap;}
.item-sub{font-weight: 400;
      color: #3c4f62;
      font-size: 10pt;
      margin-bottom: 0.3rem;}
.desc-list{list-style: none;
      padding-left: 0;
      margin-top: 0.3rem;}
.desc-list li{position: relative;
      padding-left: 1.1rem;
      margin-bottom: 0.25rem;
      font-size: 10pt;
      color: #2d3a4a;
      line-height: 1.5;}
.desc-list li::before{content: "•";
      position: absolute;
      left: 0.1rem;
      color: #2c5282;
      font-weight: 600;}
.skills-container{display: flex;
      flex-wrap: wrap;
      gap: 0.6rem 1rem;
      margin-top: 0.4rem;}
.skill-tag{font-family: 'Cascadia Code', 'Fira Code', 'Consolas', 'Monaco', 'Courier New', monospace;
      background: #f0f4f8;
      padding: 0.15rem 0.7rem;
      border-radius: 3px;
      font-size: 9.5pt;
      color: #1e2b3c;
      letter-spacing: 0.2px;
      border: 1px solid #e2e8f0;}
.code-font{font-family: 'Cascadia Code', 'Fira Code', 'Consolas', 'Monaco', 'Courier New', monospace;
      background: #f7f9fc;
      padding: 0.1rem 0.3rem;
      border-radius: 2px;
      font-size: 9.5pt;
      color: #0b2b44;}
.inline-code{font-family: 'Cascadia Code', 'Fira Code', 'Consolas', 'Monaco', monospace;
      font-size: 9.5pt;
      color: #2c5282;
      background: #f0f4f8;
      padding: 0 0.2rem;}
.two-col-list{display: flex;
      flex-wrap: wrap;
      gap: 1.5rem;}
.col{flex: 1 1 200px;}
.col ul{list-style: none;
      padding-left: 0;}
.col li{margin-bottom: 0.25rem;
      font-size: 10pt;
      display: flex;
      align-items: baseline;}
.col li::before{content: "•";
      color: #2c5282;
      font-weight: 600;
      margin-right: 0.5rem;}
.edu-item{display: flex;
      justify-content: space-between;
      margin-bottom: 0.3rem;
      font-size: 10pt;}
.edu-left{font-weight: 700;
      color: #0b2b44;}
.edu-right{color: #4a5c6c;
      font-size: 9.5pt;}

.resume-title{font-size:9pt;letter-spacing:0.1em;color:#4a5c6c;margin-bottom:10px}.misc-line{display:flex;flex-wrap:wrap;gap:2rem;font-size:10pt}.misc-item{color:#2d3a4a}.misc-item strong{color:#0b2b44}
